import{_ as a,c as i,o as l,ag as n}from"./chunks/framework.KcKrU9KS.js";const k=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"linux/Ubantu/在 WSL2安装OpenClaw.md","filePath":"linux/Ubantu/在 WSL2安装OpenClaw.md","lastUpdated":1773107605000}'),e={name:"linux/Ubantu/在 WSL2安装OpenClaw.md"};function t(p,s,h,o,d,c){return l(),i("div",null,s[0]||(s[0]=[n(`<p>对于在 Windows 11 上使用本地 Ollama 模型运行 OpenClaw 的需求，<strong>强烈建议你将 OpenClaw 安装在 WSL2 (Windows Subsystem for Linux) 中</strong>。</p><p>直接在 Windows 环境中安装可能会遇到路径、环境变量和脚本兼容性等问题，导致运行不稳定。而 WSL2 提供了一个更接近 Linux 的原生环境，这也是 OpenClaw 官方推荐和支持的运行方式，能够确保更高的稳定性和可靠性。</p><p>以下是推荐在 WSL2 中安装 OpenClaw 的核心原因和关键步骤。</p><h3 id="🤔-为什么推荐-wsl2" tabindex="-1">🤔 为什么推荐 WSL2？ <a class="header-anchor" href="#🤔-为什么推荐-wsl2" aria-label="Permalink to &quot;🤔 为什么推荐 WSL2？&quot;">​</a></h3><ul><li><strong>官方推荐</strong>：OpenClaw 官方文档明确推荐 Windows 用户通过 WSL2 来运行，这是经过验证的、最稳定的部署方式。</li><li><strong>环境兼容</strong>：OpenClaw 依赖的许多工具链和系统进程在 Linux 环境下运行更顺畅，WSL2 完美解决了原生 Windows 环境可能出现的兼容性问题。</li><li><strong>排查方便</strong>：在 WSL2 中部署，当遇到问题时，排查和解决的思路与官方文档及社区经验更一致，可以大大减少踩坑成本。</li></ul><h3 id="🛠️-核心安装步骤概览" tabindex="-1">🛠️ 核心安装步骤概览 <a class="header-anchor" href="#🛠️-核心安装步骤概览" aria-label="Permalink to &quot;🛠️ 核心安装步骤概览&quot;">​</a></h3><p>整个流程可以分为三个主要部分：准备 WSL2 环境、安装 Ollama、安装和配置 OpenClaw。</p><h4 id="_1-准备-wsl2-环境" tabindex="-1">1. 准备 WSL2 环境 <a class="header-anchor" href="#_1-准备-wsl2-环境" aria-label="Permalink to &quot;1. 准备 WSL2 环境&quot;">​</a></h4><ol><li><p><strong>安装 WSL2 和 Ubuntu</strong>：以管理员身份打开 PowerShell，运行 <code>wsl --install -d Ubuntu-24.04</code>。根据提示重启电脑，然后启动 Ubuntu 并设置用户名和密码。</p></li><li><p>启用 systemd</p><p>：OpenClaw 需要</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>systemd</span></span></code></pre></div><p>来管理后台服务。在 Ubuntu 终端中，执行以下命令创建配置文件：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tee</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/wsl.conf</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/dev/null</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;EOF&#39;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">[boot]</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">systemd=true</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">EOF</span></span></code></pre></div><p>然后，在 PowerShell 中运行</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>wsl --shutdown</span></span></code></pre></div><p>重启 WSL，再重新打开 Ubuntu 终端。</p></li><li><p><strong>安装 Node.js 和 pnpm</strong>：OpenClaw 需要 Node.js 22 或更高版本。在 Ubuntu 中安装 Git、curl 和 Node.js 22，然后安装 pnpm 包管理器。</p></li></ol><h4 id="_2-安装并配置-ollama" tabindex="-1">2. 安装并配置 Ollama <a class="header-anchor" href="#_2-安装并配置-ollama" aria-label="Permalink to &quot;2. 安装并配置 Ollama&quot;">​</a></h4><p>为了获得最佳的兼容性和网络连通性，建议将 Ollama 也安装在 WSL2 内部。</p><ol><li><p>安装 Ollama</p><p>：在 Ubuntu 终端中，运行官方安装脚本：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://ollama.com/install.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sh</span></span></code></pre></div></li><li><p>拉取模型</p><p>：启动 Ollama 服务 (</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ollama serve &amp;</span></span></code></pre></div><p>)，然后下载你需要的模型，例如</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>llama3.2</span></span></code></pre></div><p>：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ollama</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pull</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> llama3.2</span></span></code></pre></div></li><li><p><strong>验证安装</strong>：运行 <code>curl http://localhost:11434</code>，如果返回 <code>Ollama is running</code>，说明安装成功。</p></li></ol><h4 id="_3-安装和配置-openclaw" tabindex="-1">3. 安装和配置 OpenClaw <a class="header-anchor" href="#_3-安装和配置-openclaw" aria-label="Permalink to &quot;3. 安装和配置 OpenClaw&quot;">​</a></h4><ol><li><p>克隆源码</p><p>：在 Ubuntu 中，从官方 GitHub 仓库克隆 OpenClaw 项目：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/openclaw/openclaw.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> openclaw</span></span></code></pre></div></li><li><p>构建项目</p><p>：安装依赖并构建 OpenClaw：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ui:build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span></code></pre></div></li><li><p>运行配置向导</p><p>：启动交互式配置流程，并将其安装为后台服务：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> openclaw</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> onboard</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --install-daemon</span></span></code></pre></div></li><li><p>配置连接 Ollama</p><p>：在配置向导中，当提示选择模型提供商时，选择</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Custom Provider</span></span></code></pre></div><p>或类似选项，并填写以下信息：</p><ul><li><strong>API Base URL</strong>: <code>http://localhost:11434/v1</code></li><li><strong>API Key</strong>: 随便填写一个（例如 <code>ollama</code>），本地使用不校验。</li><li><strong>Endpoint compatibility</strong>: <code>OpenAI-compatible</code></li><li><strong>Model ID</strong>: 输入你之前用 Ollama 拉取的模型名称，例如 <code>llama3.2</code>。</li></ul></li></ol><p>完成以上步骤后，你就可以通过 <code>openclaw dashboard</code> 命令在浏览器中打开 OpenClaw 的控制面板，开始使用它调用本地的 Ollama 模型了。</p>`,15)]))}const g=a(e,[["render",t]]);export{k as __pageData,g as default};
